mapper.select:
SELECT el.account_id AS accountId, a.user_account AS accountName, el.game_type AS gameType, COUNT(DISTINCT DATE(el.create_time)) AS validDays FROM execution_log el LEFT JOIN account a ON el.account_id = a.id WHERE DATE_FORMAT(el.create_time, '%Y-%m') = #{yearMonth}
AND el.account_id = #{accountId}
AND el.game_type = #{gameType}
GROUP BY el.account_id, el.game_type

SELECT
    COUNT(*)
FROM (
         SELECT DISTINCT
             account_id,
             DATE(create_time)
         FROM execution_log
         WHERE DATE_FORMAT(create_time, '%Y-%m') = #{yearMonth}

             AND game_type = #{gameType}

     ) t
